import sys

sys.setrecursionlimit(5000)

class SyntaxError(Exception): pass
class NameError(Exception): pass
class TypeError(Exception): pass

class TVar:
    def __init__(self, id):
        self.id = id
        self.parent = None
    def __repr__(self):
        return f"TVar({self.id})"

class TInt:
    def __repr__(self): return "TInt"

class TBool:
    def __repr__(self): return "TBool"

class TList:
    def __init__(self, inner): self.inner = inner
    def __repr__(self): return f"TList({self.inner})"

class TTuple:
    def __init__(self, left, right):
        self.left = left
        self.right = right
    def __repr__(self): return f"TTuple({self.left}, {self.right})"

class TFunc:
    def __init__(self, arg, res):
        self.arg = arg
        self.res = res
    def __repr__(self): return f"TFunc({self.arg}, {self.res})"

class Scheme:
    def __init__(self, vars, type):
        self.vars = vars
        self.type = type

def resolve(t):
    while isinstance(t, TVar) and t.parent:
        t = t.parent
    return t

def unify(t1, t2):
    t1 = resolve(t1)
    t2 = resolve(t2)
    if t1 == t2:
        return
    if isinstance(t1, TVar):
        if occur_check(t2, t1):
            raise TypeError("Recursive type")
        t1.parent = t2
        return
    if isinstance(t2, TVar):
        unify(t2, t1)
        return
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return
    if isinstance(t1, TBool) and isinstance(t2, TBool):
        return
    if isinstance(t1, TList) and isinstance(t2, TList):
        unify(t1.inner, t2.inner)
        return
    if isinstance(t1, TTuple) and isinstance(t2, TTuple):
        unify(t1.left, t2.left)
        unify(t1.right, t2.right)
        return
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        unify(t1.arg, t2.arg)
        unify(t1.res, t2.res)
        return
    raise TypeError("Type mismatch")

def occur_check(t, v):
    t = resolve(t)
    if t == v: return True
    if isinstance(t, TFunc): return occur_check(t.arg, v) or occur_check(t.res, v)
    if isinstance(t, TTuple): return occur_check(t.left, v) or occur_check(t.right, v)
    if isinstance(t, TList): return occur_check(t.inner, v)
    return False

def get_free_vars(t, env_vars):
    t = resolve(t)
    if isinstance(t, TVar):
        return {t} if t not in env_vars else set()
    if isinstance(t, TList):
        return get_free_vars(t.inner, env_vars)
    if isinstance(t, TTuple):
        return get_free_vars(t.left, env_vars) | get_free_vars(t.right, env_vars)
    if isinstance(t, TFunc):
        return get_free_vars(t.arg, env_vars) | get_free_vars(t.res, env_vars)
    return set()

def instantiate(scheme, var_gen):
    mapping = {}
    def subst(t):
        t = resolve(t)
        if isinstance(t, TVar):
            if t in scheme.vars:
                if t not in mapping:
                    mapping[t] = var_gen()
                return mapping[t]
            return t
        if isinstance(t, TList): return TList(subst(t.inner))
        if isinstance(t, TTuple): return TTuple(subst(t.left), subst(t.right))
        if isinstance(t, TFunc): return TFunc(subst(t.arg), subst(t.res))
        return t
    return subst(scheme.type)

def generalize(t, env):
    env_vars = set()
    for s in env.values():
        env_vars |= get_free_vars(s.type, set())
    free = get_free_vars(t, env_vars)
    return Scheme(free, t)

class AST: pass
class IntLit(AST):
    def __init__(self, val): self.val = val
class BoolLit(AST):
    def __init__(self, val): self.val = val
class Name(AST):
    def __init__(self, name): self.name = name
class ListLit(AST): pass
class App(AST):
    def __init__(self, f, x): self.f, self.x = f, x
class BinOp(AST):
    def __init__(self, op, l, r): self.op, self.l, self.r = op, l, r
class Fun(AST):
    def __init__(self, args, body): self.args, self.body = args, body
class Let(AST):
    def __init__(self, x, e1, e2): self.x, self.e1, self.e2 = x, e1, e2
class LetRec(AST):
    def __init__(self, f, args, e1, e2): self.f, self.args, self.e1, self.e2 = f, args, e1, e2
class If(AST):
    def __init__(self, c, t, e): self.c, self.t, self.e = c, t, e
class Tuple(AST):
    def __init__(self, l, r): self.l, self.r = l, r

class Lexer:
    def __init__(self, src):
        self.src = src
        self.pos = 0
    def peek(self):
        while self.pos < len(self.src) and self.src[self.pos].isspace(): self.pos += 1
        if self.pos >= len(self.src): return None
        c = self.src[self.pos]
        if c.isdigit():
            start = self.pos
            while self.pos < len(self.src) and self.src[self.pos].isdigit(): self.pos += 1
            res = self.src[start:self.pos]
            self.pos = start
            return res
        if c.isalpha() or c == '_':
            start = self.pos
            while self.pos < len(self.src) and (self.src[self.pos].isalnum() or self.src[self.pos] in '_\' '):
                if self.src[self.pos] == ' ': break
                self.pos += 1
            res = self.src[start:self.pos]
            self.pos = start
            return res
        if self.src.startswith('->', self.pos):
            return '->'
        if self.src.startswith('::', self.pos):
            return '::'
        return c
    def consume(self, expected=None):
        t = self.peek()
        if t is None: raise SyntaxError()
        if expected and t != expected: raise SyntaxError()
        # To actually consume, move pos forward by length of token
        p = self.pos
        while p < len(self.src) and self.src[p].isspace(): p += 1
        if p >= len(self.src): raise SyntaxError()
        c = self.src[p]
        if c.isdigit():
            while p < len(self.src) and self.src[p].isdigit(): p += 1
        elif c.isalpha() or c == '_':
            while p < len(self.src) and (self.src[p].isalnum() or self.src[p] in '_\' '):
                if self.src[p] == ' ': break
                p += 1
        elif self.src.startswith('->', p): p += 2
        elif self.src.startswith('::', p): p += 2
        else: p += 1
        self.pos = p
        return t

class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
    def match(self, s):
        if self.lexer.peek() == s:
            self.lexer.consume()
            return True
        return False
    def parse_name(self):
        n = self.lexer.consume()
        if n in ("fun", "let", "rec", "in", "if", "then", "else", "true", "false"):
            raise SyntaxError()
        return n
    def parse_expr(self):
        if self.match("fun"):
            args = []
            while self.lexer.peek() != "->":
                args.append(self.parse_name())
            self.lexer.consume("->")
            return Fun(args, self.parse_expr())
        if self.match("let"):
            if self.match("rec"):
                f = self.parse_name()
                args = []
                while self.lexer.peek() not in ("=", "in"):
                    args.append(self.parse_name())
                self.lexer.consume("=")
                e1 = self.parse_expr()
                self.lexer.consume("in")
                e2 = self.parse_expr()
                return LetRec(f, args, e1, e2)
            else:
                x = self.parse_name()
                args = [x]
                while self.lexer.peek() not in ("=", "in") and (self.lexer.peek() and (self.lexer.peek().isalpha() or self.lexer.peek() == '_')):
                    args.append(self.parse_name())
                if self.lexer.peek() == "=":
                    self.lexer.consume("=")
                    e1 = self.parse_expr()
                    self.lexer.consume("in")
                    e2 = self.parse_expr()
                    if len(args) > 1: return Let(args[0], Fun(args[1:], e1), e2)
                    return Let(args[0], e1, e2)
                raise SyntaxError()
        if self.match("if"):
            e1 = self.parse_expr()
            self.lexer.consume("then")
            e2 = self.parse_expr()
            self.lexer.consume("else")
            e3 = self.parse_expr()
            return If(e1, e2, e3)
        return self.parse_priority2()
    def parse_priority2(self):
        e = self.parse_priority3()
        while self.lexer.peek() in ("=", "<"):
            op = self.lexer.consume()
            e = BinOp(op, e, self.parse_priority3())
        return e
    def parse_priority3(self):
        e = self.parse_priority4()
        if self.lexer.peek() == "::":
            op = self.lexer.consume()
            e = BinOp(op, e, self.parse_priority3())
        return e
    def parse_priority4(self):
        e = self.parse_priority5()
        while self.lexer.peek() in ("+", "-"):
            op = self.lexer.consume()
            e = BinOp(op, e, self.parse_priority5())
        return e
    def parse_priority5(self):
        e = self.parse_priority6()
        while self.lexer.peek() == "*":
            op = self.lexer.consume()
            e = BinOp(op, e, self.parse_priority6())
        return e
    def parse_priority6(self):
        e = self.parse_atom()
        while self.lexer.peek() not in (None, ")", ",", "->", "in", "then", "else", "=", "<", "::", "+", "-", "*"):
            e = App(e, self.parse_atom())
        return e
    def parse_atom(self):
        if self.match("("):
            e = self.parse_expr()
            if self.match(","):
                e2 = self.parse_expr()
                self.lexer.consume(")")
                return Tuple(e, e2)
            self.lexer.consume(")")
            return e
        if self.match("["):
            self.lexer.consume("]")
            return ListLit()
        t = self.lexer.peek()
        if t == "true": self.lexer.consume(); return BoolLit(True)
        if t == "false": self.lexer.consume(); return BoolLit(False)
        if t and t[0].isdigit(): return IntLit(int(self.lexer.consume()))
        if t and (t[0].isalpha() or t == '_'): return Name(self.lexer.consume())
        raise SyntaxError()

def infer_type(ast, env, var_gen):
    if isinstance(ast, IntLit): return TInt()
    if isinstance(ast, BoolLit): return TBool()
    if isinstance(ast, ListLit): return TList(TVar(var_gen()))
    if isinstance(ast, Name):
        if ast.name not in env: raise NameError(ast.name)
        return instantiate(env[ast.name], var_gen)
    if isinstance(ast, App):
        tf = infer_type(ast.f, env, var_gen)
        tx = infer_type(ast.x, env, var_gen)
        tr = TVar(var_gen())
        unify(tf, TFunc(tx, tr))
        return tr
    if isinstance(ast, BinOp):
        tl = infer_type(ast.l, env, var_gen)
        tr = infer_type(ast.r, env, var_gen)
        if ast.op == "::":
            t_res = TVar(var_gen())
            unify(tl, TFunc(tr, TFunc(TList(t_res), t_res))) # wait, :: is 'a -> 'a list -> 'a list
            t_a = TVar(var_gen())
            unify(tl, t_a)
            unify(tr, TList(t_a))
            return TList(t_a)
        if ast.op in ("+", "-", "*"):
            unify(tl, TInt())
            unify(tr, TInt())
            return TInt()
        if ast.op == "<":
            unify(tl, TInt())
            unify(tr, TInt())
            return TBool()
        if ast.op == "=":
            t_a = TVar(var_gen())
            unify(tl, t_a)
            unify(tr, t_a)
            return TBool()
    if isinstance(ast, Fun):
        arg_types = [TVar(var_gen()) for _ in ast.args]
        new_env = env.copy()
        for i in range(len(ast.args)):
            new_env[ast.args[i]] = Scheme([], arg_types[i])
        res_type = infer_type(ast.body, new_env, var_gen)
        final_type = res_type
        for t in reversed(arg_types):
            final_type = TFunc(t, final_type)
        return final_type
    if isinstance(ast, Let):
        t1 = infer_type(ast.e1, env, var_gen)
        s1 = generalize(t1, env)
        new_env = env.copy()
        new_env[ast.x] = s1
        return infer_type(ast.e2, new_env, var_gen)
    if isinstance(ast, LetRec):
        t_f = TVar(var_gen())
        arg_types = [TVar(var_gen()) for _ in ast.args]
        rec_env = env.copy()
        rec_env[ast.f] = Scheme([], t_f)
        for i in range(len(ast.args)):
            rec_env[ast.args[i]] = Scheme([], arg_types[i])
        t_body = infer_type(ast.e1, rec_env, var_gen)
        final_f_type = t_body
        for t in reversed(arg_types):
            final_f_type = TFunc(t, final_f_type)
        unify(t_f, final_f_type)
        s_f = generalize(final_f_type, env)
        new_env = env.copy()
        new_env[ast.f] = s_f
        return infer_type(ast.e2, new_env, var_gen)
    if isinstance(ast, If):
        tc = infer_type(ast.c, env, var_gen)
        unify(tc, TBool())
        tt = infer_type(ast.t, env, var_gen)
        te = infer_type(ast.e, env, var_gen)
        unify(tt, te)
        return tt
    if isinstance(ast, Tuple):
        tl = infer_type(ast.l, env, var_gen)
        tr = infer_type(ast.r, env, var_gen)
        return TTuple(tl, tr)

def type_to_str(t, mapping):
    t = resolve(t)
    if isinstance(t, TInt): return "int"
    if isinstance(t, TBool): return "bool"
    if isinstance(t, TVar):
        if t not in mapping:
            idx = len(mapping)
            char = chr(ord('a') + (idx % 26))
            num = idx // 26
            mapping[t] = f"'{char}{num if num > 0 else ''}"
        return mapping[t]
    if isinstance(t, TList):
        inner = type_to_str(t.inner, mapping)
        if isinstance(resolve(t.inner), (TFunc, TTuple)):
            return f"({inner}) list"
        return f"{inner} list"
    if isinstance(t, TTuple):
        l = type_to_str(t.left, mapping)
        r = type_to_str(t.right, mapping)
        if isinstance(resolve(t.left), (TFunc, TTuple)): l = f"({l})"
        if isinstance(resolve(t.right), (TFunc, TTuple)): r = f"({r})"
        return f"{l} * {r}"
    if isinstance(t, TFunc):
        arg = type_to_str(t.arg, mapping)
        res = type_to_str(t.res, mapping)
        if isinstance(resolve(t.arg), (TFunc, TTuple)): arg = f"({arg})"
        return f"{arg} -> {res}"

def infer(src: str) -> str:
    lexer = Lexer(src)
    parser = Parser(lexer)
    try:
        ast = parser.parse_expr()
        if lexer.peek() is not None: raise SyntaxError()
    except (SyntaxError, IndexError):
        raise SyntaxError()

    env = {
        "fst": Scheme([], TFunc(TVar(0), TFunc(TTuple(TVar(1), TVar(2)), TVar(1)))), # wait, this is wrong.
    }
    # Better initialize build-ins with proper types
    v_gen_idx = 0
    def var_gen():
        nonlocal v_gen_idx
        v_gen_idx += 1
        return TVar(v_gen_idx)

    # Build-ins
    va, vb = TVar(1000), TVar(1001)
    env = {
        "fst": Scheme({va, vb}, TFunc(TTuple(va, vb), va)),
        "snd": Scheme({va, vb}, TFunc(TTuple(va, vb), vb)),
        "hd": Scheme({va}, TFunc(TList(va), va)),
        "tl": Scheme({va}, TFunc(TList(va), TList(va))),
        "null": Scheme({va}, TFunc(TList(va), TBool())),
    }

    try:
        t_res = infer_type(ast, env, var_gen)
        return type_to_str(resolve(t_res), {})
    except (TypeError, NameError):
        raise
